preConditionHook:
// TAKE PROFITS INTO THE SECOND CLIMAX. Once minClimaxes separated same-
// direction climax bars have printed inside the last windowBars, Brooks says to
// be out: either sell into the climax bar's own close, or wait for the first
// bar that closes against the position. exitOnClimaxClose picks between them --
// 1 exits on the climax bar itself, 0 (the default) waits for the first
// opposite-body bar. Both readings are in the quote, and neither is worth its
// own rule.
//
// THIS CANNOT BE COMPOSED FROM ConsecutiveClimaxBarCount. That rule is an Entry,
// exits are ORed rather than ANDed, and an Entry cannot sit in the exit pane --
// the same reason ConsecutiveCloseExit exists alongside MomentumConsecutiveBars
// and ConsecutiveTrendBarsClimaxExit alongside StrongTrendBarRun. Not
// ConsecutiveTrendBarsClimaxExit either: that wants a RUN of consecutive trend
// bars and a profit gate, where this wants SEPARATED climaxes and no profit
// gate, so the two leave on different bars.
//
// THE COUNT IS ConsecutiveClimaxBarCount's, unchanged: ClimaxBar's test
// evaluated at each bar of the window against the CURRENT ATR -- one ATR read,
// not one per counted bar, which keeps the rule off the ATR variable's own
// history -- and a climax counts only when it is SEPARATED from the run before
// it, i.e. at least one of the maxGapBars bars immediately older than it is not
// itself a climax of the same direction. windowBars is 15 here rather than that
// rule's 30, which is the source's own window.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. The block is AtrProfitTarget's and ClimaxBar's verbatim, including
// the TWO separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently and lands on the other side of a threshold.
// It stays in the hook, which the generator emits unconditionally: EasyLanguage
// does not short-circuit, so a stateful call inside a condition would advance
// every bar in EL and only on some bars here.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// Deepest bar touched: max(windowBars + maxGapBars - 1, atrLength + 1).
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
bullCount = 0.0;
bearCount = 0.0;
for (ii = 0; ii < (int)windowBars; ++ii) {
    isBull = el_gt(close[ii], open[ii])
        && el_ge(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], climaxMultiple * atrValue);
    isBear = el_lt(close[ii], open[ii])
        && el_ge(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], climaxMultiple * atrValue);
    sepBull = false;
    sepBear = false;
    for (jj = ii + 1; jj <= ii + (int)maxGapBars; ++jj) {
        gapBull = el_gt(close[jj], open[jj])
            && el_ge(close[jj] - open[jj], bodyFraction * (high[jj] - low[jj]))
            && el_ge(high[jj] - low[jj], climaxMultiple * atrValue);
        gapBear = el_lt(close[jj], open[jj])
            && el_ge(open[jj] - close[jj], bodyFraction * (high[jj] - low[jj]))
            && el_ge(high[jj] - low[jj], climaxMultiple * atrValue);
        if (!gapBull) sepBull = true;
        if (!gapBear) sepBear = true;
    }
    if (isBull && sepBull) bullCount += 1;
    if (isBear && sepBear) bearCount += 1;
}
